'use strict';
// Policy pages. They describe what this site actually does: free play credits, saves kept in the
// browser, optional Discord sign-in, and a small chat server. Keep them in step with the code.
const LEGAL_UPDATED='21 November 2026';
const legalPages={
  terms:{title:'Terms of Service',body:
    '<h3>1. What DriftLobby is</h3><p>DriftLobby is a private arcade of casino-style games played for fun with free play credits. It is not a gambling service. No real money is taken, held, or paid out, and nothing here is for sale.</p>'+
    '<h3>2. Play credits</h3><ul><li>Credits are a score. They have no cash value.</li><li>Credits cannot be bought, sold, or redeemed for money, goods, or prizes.</li><li>Signed-in players can tip credits to each other inside DriftLobby. A tip is still only play credits, and it cannot be undone.</li><li>Signed-in players can also stake credits against each other in player coin flips. The winner receives both stakes; these are play credits like any others.</li><li>Every profile starts with 1,000 credits and can refill for free when it drops below 10.</li><li>Credits are saved in your own browser. Clearing site data, switching device, or a reset by the host can remove them, and they cannot be restored.</li><li>The DriftLobby Discord bot keeps its own balance for each player, separate from the one on this site. Those credits are free in the same way: they start at 1,000, come from free refills and tips, and cannot be bought, deposited, withdrawn, or cashed out.</li></ul>'+
    '<h3>3. Who may use it</h3><p>DriftLobby is for people the host has invited. You must be old enough under your local rules to play casino-style social games. Signing in with Discord also requires that you meet Discord’s own age rules.</p>'+
    '<h3>4. No outside stakes</h3><p>Do not use DriftLobby to place, settle, or keep track of bets involving real money or anything of value. If someone asks you to pay for credits or for access, it is not part of this site.</p>'+
    '<h3>5. Fair use</h3><p>Play the games as they are offered. Do not edit saved data, tamper with the code, exploit faults, or interfere with other players or the chat server. Edited or damaged saves may be reset.</p>'+
    '<h3>6. Discord sign-in and chat</h3><p>Signing in with Discord is optional and is needed to send chat messages. Chat is covered by the Community Rules. The host may remove messages or access at any time.</p>'+
    '<h3>7. Simulated activity</h3><p>Some chat messages, the characters who post them, and part of the online count are simulated by the site for atmosphere. They are not real people, and their replies may be written by AI.</p>'+
    '<h3>8. Availability</h3><p>DriftLobby is a hobby project provided as it is, with no guarantee that it will be available, free of faults, or kept running. Games, odds, and features may change at any time.</p>'+
    '<h3>9. Liability</h3><p>As far as the law allows, the host is not liable for lost credits, lost data, or time spent. Nothing in these terms limits rights that cannot legally be limited.</p>'+
    '<h3>10. Changes and contact</h3><p>These terms may be updated; the date above shows the latest version. Questions go to the person who gave you access to DriftLobby.</p>'},
  privacy:{title:'Privacy Policy',body:
    '<h3>In short</h3><p>DriftLobby has no adverts, no analytics, and no tracking. Your game data stays in your browser. The only things that leave it are your Discord sign-in checks and the chat messages you choose to send.</p>'+
    '<h3>Saved in your browser</h3><ul><li>Your profile: display name, credits, favourites, the last 50 rounds, the last 100 credit movements, live stats, and any unfinished round.</li><li>Settings: sound, motion, chat, and display choices.</li><li>If you sign in: your Discord ID, username, display name, picture reference, and the sign-in token Discord issued.</li></ul><p>This is kept in the browser’s local storage on your device. The host cannot see it.</p>'+
    '<h3>Discord sign-in</h3><p>Sign-in asks Discord only for your basic identity (the “identify” permission). DriftLobby never sees your Discord password or email address. Your token is sent to Discord to read your name and picture, and to the chat server when you send a message so it can confirm who you are.</p>'+
    '<h3>Chat</h3><ul><li>Messages you send go to the chat server run by the host and are shown to everyone connected.</li><li>The server keeps the latest 50 messages in memory, with the sender’s display name, Discord ID, picture reference, and the time. They are lost when the server restarts.</li><li>Like any web server, it receives your IP address while you are connected. The chat software does not record it.</li></ul>'+
    '<h3>AI replies</h3><p>The host can switch on AI-written replies for the chat characters. When that is on, the chat messages you send and the display name on them are passed from the chat server to Anthropic’s Claude API so it can write those replies. Nothing else about you is sent, and it is not used when AI replies are off.</p>'+
    '<h3>Player flips</h3><p>A coin flip you create or join is shown to everyone on the site with your display name, picture, and stake. A finished flip leaves the list after 20 minutes. The chat server keeps open flips and any credits owed to you until your browser collects them.</p>'+
    '<h3>Discord bot</h3><p>If you use the DriftLobby bot in a Discord server, the bot keeps a record under your Discord ID on the host’s computer: your display name, your bot balance, your totals (rounds, wins, amount bet and returned, best win, biggest bet), and any stake in an unfinished round or flip. The games you play, your tips, and the leaderboard are posted in the channel where you use the commands, as with any Discord bot. To answer commands typed with $, the bot is sent the messages posted in channels it can see; it acts only on messages that start with a command and keeps none of them. In servers the host has set up, the bot gives you rank roles based on how much you have bet, which other members can see. This record is separate from what the website saves in your browser. Ask the host if you want it removed.</p>'+
    '<h3>Tips</h3><p>To confirm a tip, the DriftLobby bot sends a code to your Discord direct messages. The chat server keeps the unconfirmed tip (your Discord ID, who it is for, the amount, and the code) for a few minutes, and keeps a confirmed tip until the other person next opens the site. A confirmed tip is also shown in chat.</p>'+
    '<h3>Other services</h3><p>Discord handles sign-in and serves profile pictures, so Discord receives your IP address and whatever its own policy describes when those load. The company hosting the site can see ordinary web requests.</p>'+
    '<h3>Simulated chatter</h3><p>Simulated chat is generated in your browser. It is not sent anywhere.</p>'+
    '<h3>Your choices</h3><ul><li>Sign out from the profile button at any time.</li><li>Settings → Data on this browser lets you clear history, reset a profile, or erase everything DriftLobby has saved.</li><li>You can remove DriftLobby’s access in Discord under User Settings → Authorized Apps.</li></ul>'+
    '<h3>Children</h3><p>DriftLobby is not directed at children under 13 and does not knowingly collect their information.</p>'+
    '<h3>Changes and contact</h3><p>This policy may be updated; the date above shows the latest version. Questions go to the person who gave you access to DriftLobby.</p>'},
  refunds:{title:'Refund Policy',body:
    '<h3>There is nothing to refund</h3><p>DriftLobby does not sell anything. Credits are free, access is free, and the site takes no payments of any kind: no cards, no bank transfers, no cryptocurrency, no gift cards, no in-game items.</p>'+
    '<h3>If you were asked to pay</h3><p>Anyone asking for payment for DriftLobby credits or access is not acting for this site. Do not pay, and tell the person who gave you access.</p>'+
    '<h3>Tips</h3><p>A tip of play credits to another player is final once you confirm it with your code. It cannot be reversed, and since credits have no cash value there is nothing to refund.</p>'+
    '<h3>Lost credits</h3><p>Credits are a score saved in your browser. If they are lost through a fault, cleared site data, a reset, or a change of device, they cannot be restored, but a profile can always refill for free when it drops below 10 credits.</p>'},
  fairness:{title:'Fair Play and Odds',body:
    '<h3>How results are decided</h3><ul><li>Every result comes from your browser’s cryptographic random number generator.</li><li>In nine games the size of your bet changes your chance of winning, as set out below. No game looks at your balance or your history.</li><li>Results that have not been played yet are not worked out or saved ahead of time.</li></ul>'+
    '<h3>Bigger bets win less often</h3><p>This applies to Tower, Mines, Limbo, Dice, Hi-Lo, Coinflip, Rock Paper Scissors, Wheel, and War. A win in these games always pays the full amount for the odds: 2× on a coin flip, 3× a floor on a one-in-three Tower, and so on. What changes with the bet is how often you win.</p><ul><li><b>1 to 200 credits:</b> you keep nearly all of the normal chance. It slides from 100% of it at 1 credit to 97% at 10, 94% at 100, and about 93% at 200.</li><li><b>Over 200 credits:</b> you keep 60% of the normal chance. On an even-money bet such as a coin flip that is a 30% chance to win and a 70% chance for the house.</li><li><b>Over 1,500 credits:</b> the bet cannot win. The house takes it every time.</li></ul><p>The chance for the bet you have typed is shown under the bet amount before you play, and each table’s “Win chance” line uses it. In Tower, Mines, and Hi-Lo, which are played pick by pick, the bet size counts on the first floor, first tile, or first winning call only; later picks have the normal chance. Ties in War and Rock Paper Scissors still return the bet. When the house takes a round you would have won, the result shown is a losing one: the coin shows the other face, the dice land outside your range, the wheel stops on a 0× segment.</p>'+
    '<h3>The other games</h3><p>These do not look at the size of the bet.</p><ul><li><b>Plinko:</b> pays back between 97.5% and 100%, depending on rows and risk.</li><li><b>Roulette:</b> a single-zero wheel with 37 pockets, which pays back 97.3%.</li><li><b>Keno:</b> pays back between about 58% and 95%, depending on how many numbers you pick.</li><li><b>Blackjack:</b> one 52-card deck per round, dealer stands on all 17s, a natural pays 3 to 2.</li><li><b>Baccarat:</b> Player returns 2×, Banker 1.9×, and a correct Tie 9×.</li><li><b>Player flips:</b> two players stake the same amount on opposite sides. After a ten-second countdown the chat server tosses one fair coin; the result is not chosen before the countdown ends, and the size of the stake makes no difference. The winner gets both stakes, and nothing is taken as a fee.</li></ul><p>Each table’s “Table rules” lists its exact rules.</p>'+
    '<h3>The Discord bot</h3><p>The DriftLobby bot runs the same game code as this site, so its odds are the same, including the way bigger bets win less often. Each game message states the chance for the bet that was made, its how-to-play guide sets out the figures above, and it asks for confirmation before taking a bet over 1,500 in a game where that bet cannot win. Its Mines board has 20 tiles. Its rank roles follow the total a player has bet, and its two high roller roles follow the biggest single bet (500 and 1,000 credits); no role is given for a bet over 1,500. Blackjack, Roulette, Plinko, and player flips do not look at the size of the bet there either.</p>'+
    '<h3>Tamper protection</h3><p>Saved profiles are sealed. A save that has been edited outside the game is detected and that profile is reset. Because the games run in your own browser, this deters tampering but cannot make it impossible; scores here are for fun, not proof of anything.</p>'},
  community:{title:'Community Rules',body:
    '<h3>Be decent</h3><ul><li>No harassment, threats, hate, or sexual content.</li><li>No sharing of anyone’s personal information, including your own contact details.</li><li>No spam, flooding, or advertising.</li><li>No impersonating other people.</li></ul>'+
    '<h3>Keep money out of it</h3><ul><li>No offers to buy, sell, or trade credits.</li><li>No real-money bets, tips, loans, or giveaways. Tips of play credits inside the site are fine.</li><li>No links to gambling sites, scams, or downloads.</li></ul>'+
    '<h3>How chat works</h3><ul><li>Messages are limited to 200 characters and one per second.</li><li>Type @ and a name to mention someone; they see your message highlighted.</li><li>The host can remove messages or access for anyone who breaks these rules. Tell the host if someone is causing trouble.</li></ul>'},
  responsible:{title:'Play Responsibly',body:
    '<h3>It is a game</h3><p>DriftLobby is play money. You cannot win or lose anything of value here, and a high balance means nothing outside the arcade.</p>'+
    '<h3>Keep it fun</h3><ul><li>Take breaks, and stop when it stops being fun.</li><li>Casino-style games can form habits even without money involved. Notice if you are playing longer than you meant to.</li><li>Results are random. No system, streak, or feeling changes the odds. In some games the size of the bet does: bigger bets win less often, as the Fair Play page sets out.</li></ul>'+
    '<h3>If real-money gambling is a problem</h3><p>If gambling with real money is causing harm to you or someone you know, free and confidential help is available. In the United States, call 1-800-GAMBLER. In the United Kingdom, contact GamCare or BeGambleAware. Elsewhere, search for your national gambling helpline.</p>'},
  storage:{title:'Cookies and Storage',body:
    '<h3>No cookies</h3><p>DriftLobby does not set cookies and does not use advertising or analytics tools.</p>'+
    '<h3>What is stored instead</h3><p>The site uses your browser’s local storage so the arcade remembers you on this device:</p><ul><li>Player profiles, credits, and history.</li><li>Sound, motion, chat, and display settings.</li><li>Whether the chat panel and profit tracker are open, and where the tracker sits.</li><li>Your Discord sign-in, if you connect one.</li><li>A seal used to detect edited saves.</li></ul><p>A short-lived session entry remembers that the opening animation has played and carries you through Discord sign-in.</p>'+
    '<h3>Clearing it</h3><p>Use Settings → Data on this browser → Erase all, or clear this site’s data in your browser. Discord sets its own cookies on its own pages when you sign in there.</p>'}
};
const legalLinks=()=>Object.entries(legalPages).map(([key,page])=>'<button type="button" data-legal="'+key+'">'+page.title+'</button>').join('');
function openLegal(key){
  const page=legalPages[key];
  if(!page)return;
  panel('DRIFTLOBBY',page.title,'<div class="info legal"><p class="legal-date">Last updated '+LEGAL_UPDATED+'</p>'+page.body+'<nav class="legal-links" aria-label="Other policies">'+legalLinks()+'</nav></div>');
}
if(typeof document!=='undefined'){
  document.addEventListener('click',e=>{const link=e.target.closest('[data-legal]');if(link)openLegal(link.dataset.legal)});
  document.querySelector('#legalFooter')?.insertAdjacentHTML('beforeend',legalLinks());
}
